"""CI-only Source tests. No execution or PG qualification claimed by this file.

The typed CI views below are declared test operands, not actual CI receipts.
The old guard/CHECKs and Root97 bytes are retained genuine public originals;
new full function bodies come from exact M98 Source, never executed here.
"""
import copy
import hashlib
import importlib.util
import json
from pathlib import Path
import unittest


def canonical(value):
    return (json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False) + '\n').encode()


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def load_catalog98():
    here = Path(__file__).resolve().parent
    path = here / 'catalog98_helpers.INERT.py'
    if not path.exists():
        path = here.parent / 'rollout' / 'catalog98_helpers.py'
    spec = importlib.util.spec_from_file_location('declared_catalog98_ci_source', path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def legacy_c9_bytes():
    return LEGACY_C9_RAW


def declared_catalog98():
    return fixture98()


